const reminderWindowStartHours = 23
const reminderWindowEndHours = 25

const appointment = $json
const currentTime = new Date()
const appointmentStartTime = new Date(appointment.startTime)

let isEligible = true
let ineligibilityReason = null

if (!appointment.appointmentId) {
  isEligible = false
  ineligibilityReason = "Appointment ID is missing"
} else if (appointment.status !== "confirmed") {
  isEligible = false
  ineligibilityReason = `Appointment status is ${appointment.status}`
} else if (!appointment.phone && !appointment.email) {
  isEligible = false
  ineligibilityReason = "No phone number or email address"
} else if (Number.isNaN(appointmentStartTime.getTime())) {
  isEligible = false
  ineligibilityReason = "Appointment start time is invalid"
} else if (appointmentStartTime <= currentTime) {
  isEligible = false
  ineligibilityReason = "Appointment is not in the future"
} else {
  const millisecondsUntilAppointment =
    appointmentStartTime.getTime() - currentTime.getTime()

  const hoursUntilAppointment =
    millisecondsUntilAppointment / (1000 * 60 * 60)

  const isInsideReminderWindow =
    hoursUntilAppointment >= reminderWindowStartHours &&
    hoursUntilAppointment < reminderWindowEndHours

  if (!isInsideReminderWindow) {
    isEligible = false
    ineligibilityReason = "Appointment is outside the reminder window"
  }
}

const reminderType = "24-hour"

const reminderKey = [
  appointment.appointmentId,
  appointment.startTime,
  reminderType
].join(":")

return {
  json: {
    ...appointment,
    reminderType,
    reminderKey,
    isEligible,
    ineligibilityReason,
    evaluatedAt: currentTime.toISOString()
  }
}
